mapper.select:
select 
  po.po_id,
  po.order_type,
  po.display_number,
  CONCAT_WS(' ', u.last_name, u.first_name) as purchaser,


  po.delivery_due_date,

  po.service_period_from,
  po.service_period_to,

  po.snap_supplier_name as supplier_name,
  po.total_amount_excluding_tax,
  po.status
from purchase_order po
left join supplier s
  on po.supplier_id = s.supplier_id
join users u
  on po.purchaser_user_id = u.user_id


     po.purchaser_user_id = #{userId}



    and po.order_type = #{form.orderType}




        and 
          (
            po.delivery_due_date >= #{form.targetDateFrom}
            or po.service_period_to >= #{form.targetDateFrom}
          )


         and po.delivery_due_date >= #{form.targetDateFrom}


         and po.service_period_to >= #{form.targetDateFrom}






        and 
          (
            po.delivery_due_date <= #{form.targetDateTo}
            or po.service_period_from <= #{form.targetDateTo}
          )


         and po.delivery_due_date <= #{form.targetDateTo}


         and po.service_period_from <= #{form.targetDateTo}




    and s.supplier_id = #{form.supplierId}


    and po.status = #{form.status}



    and ( 
      po.display_number::varchar ~ #{form.keywordRegex}
      or normalization(lower(concat(u.last_name, u.first_name))) ~#{form.keywordRegex}
      or normalization(lower(concat(u.last_name_kana, u.first_name_kana))) ~#{form.keywordRegex}
      or normalization(lower(s.name)) ~#{form.keywordRegex}
      or normalization(lower(s.name_kana)) ~#{form.keywordRegex}
    )


order by

    po.display_number

    case po.order_type
      when 'STANDARD' then 1
      when 'SERVICE' then 2
    end

    concat(u.last_name_kana, u.first_name_kana)



          coalesce(po.delivery_due_date, po.service_period_from) asc,
          coalesce(po.delivery_due_date, po.service_period_to) asc


          coalesce(po.delivery_due_date, po.service_period_to) desc,
          coalesce(po.delivery_due_date, po.service_period_from) desc



    s.name_kana
    po.total_amount_excluding_tax

    case po.status
      when 'PENDING' then 1
      when 'APPROVED' then 2
      when 'REJECTED' then 3
      when 'COMPLETED' then 4
      when 'CANCELLED' then 5
    end





  , po.display_number 
limit #{form.size} offset #{form.offset}

select count(*)
from purchase_order po
left join supplier s
  on po.supplier_id = s.supplier_id
join users u
  on po.purchaser_user_id = u.user_id


     po.purchaser_user_id = #{userId}



    and po.order_type = #{form.orderType}




        and 
          (
            po.delivery_due_date >= #{form.targetDateFrom}
            or po.service_period_to >= #{form.targetDateFrom}
          )


         and po.delivery_due_date >= #{form.targetDateFrom}


         and po.service_period_to >= #{form.targetDateFrom}






        and 
          (
            po.delivery_due_date <= #{form.targetDateTo}
            or po.service_period_from <= #{form.targetDateTo}
          )


         and po.delivery_due_date <= #{form.targetDateTo}


         and po.service_period_from <= #{form.targetDateTo}




    and s.supplier_id = #{form.supplierId}


    and po.status = #{form.status}



    and ( 
      po.display_number::varchar ~ #{form.keywordRegex}
      or normalization(lower(concat(u.last_name, u.first_name))) ~#{form.keywordRegex}
      or normalization(lower(concat(u.last_name_kana, u.first_name_kana))) ~#{form.keywordRegex}
      or normalization(lower(s.name)) ~#{form.keywordRegex}
      or normalization(lower(s.name_kana)) ~#{form.keywordRegex}
    )

select po.po_id, po.display_number, po.order_type, po.snap_supplier_name as supplier_name, u.user_id, CONCAT_WS(' ', u.last_name, u.first_name) as purchaser, po.total_amount_excluding_tax, po.status, po.note, CAST(po.created_at AS DATE) as created_at,
po.delivery_due_date,
po.service_period_from, po.service_period_to,
pr.pr_id, pr.display_number as pr_display_number from purchase_order po join users u on po.purchaser_user_id = u.user_id left join purchase_request_purchase_order prpo on po.po_id = prpo.po_id left join purchase_request pr on pr.pr_id = prpo.pr_id where po.po_id = #{poId}
and po.purchaser_user_id = #{userId}
order by pr.display_number asc

select coalesce(#{supplierId}, #{supplierName}) as mapping_key, coalesce(s.name, #{supplierName}) as supplier_name, concat_ws(' ', u.last_name, u.first_name) as purchaser, pt.name as payment_term_name, pr.display_number, prd.pr_detail_id, prd.item_id, prd.unit_id, prd.snap_item_name, prd.snap_unit_name, prd.snap_unit_price, prd.quantity from purchase_request pr join purchase_request_detail prd on pr.pr_id = prd.pr_id join users u on u.user_id = #{userId} left join supplier s on prd.supplier_id = s.supplier_id left join payment_term pt on s.payment_term_id = pt.payment_term_id where prd.pr_detail_id in
#{prDetailId}
and prd.supplier_id = #{supplierId}
and prd.supplier_id is null and prd.snap_supplier_name = #{supplierName}
order by pr.display_number asc, prd.line_no asc
